use vstd::prelude::*;

verus! {

fn getdomain(x: Vec<i8>) -> (result: Vec<i8>)
    requires
        // input must be non‐empty
        x.len() > 0,
    ensures
        // result is exactly two elements: [min, max]
        result.len() == 2,
        // the first element is ≤ the second
        result[0] <= result[1],
        // every input lies between min and max
        forall |k: usize| k < x.len() ==> result[0] <= x[k] <= result[1],
        // min and max must actually occur in the input
        exists |k: usize| k < x.len() && x[k] == result[0],
        exists |k: usize| k < x.len() && x[k] == result[1],
{
    // initialize min and max to the first element
    let mut min: i8 = x[0];
    let mut max: i8 = x[0];
    let n: usize = x.len();
    let mut i: usize = 1;

    // scan the rest of the array
    while i < n
        invariant
            // loop index stays in range
            i <= n,
            // min and max are ordered
            min <= max,
            // for all j < i, we have min ≤ x[j] ≤ max
            forall |j: usize| j < i ==> min <= x[j] <= max,
            // there is some j < i with x[j] = min
            exists |j: usize| j < i && x[j] == min,
            // there is some j < i with x[j] = max
            exists |j: usize| j < i && x[j] == max,
        decreases n - i,
    {
        let v: i8 = x[i];
        if v < min {
            min = v;
        }
        if v > max {
            max = v;
        }
        i = i + 1;
    }

    // build result vector [min, max]
    let mut res: Vec<i8> = Vec::new();
    res.push(min);
    res.push(max);
    res
}

} // verus!

